steps.css:
.karte {
  background-color: lightblue;
  color: navy;
  padding: 20px;
  margin-bottom: 16px;
  border: 2px solid navy;
  border-radius: 12px;
}

.karte:hover {
  background-color: gold;
}

body {
  background-color: ivory;
}

details {
  padding: 12px;
  border: 1px solid teal;
  border-radius: 8px;
}

summary {
  cursor: pointer;
}

th, td {
  border: 1px solid teal;
  padding: 8px;
  text-align: left;
}

th {
  background-color: lightblue;
}

.karte {
  background-color: lightblue;
  color: navy;
  padding: 20px;
  border: 2px solid navy;
  border-radius: 12px;
  transition: background-color 1s;
}

.karte:hover {
  background-color: gold;
}
